const https=require('https');const dns=require('dns');
function get(host,path){return new Promise(r=>{const q=https.get({host,path,timeout:12000},res=>{let d='';res.on('data',c=>d+=c);res.on('end',()=>r(res.statusCode+' server='+(res.headers['server']||'-')+' '+d.slice(0,120).replace(/\n/g,' ')));});q.on('error',e=>r('ERR '+e.code));q.on('timeout',()=>{q.destroy();r('TIMEOUT')});});}
